import {uid,clone} from './storage.js';
import {icon} from './icons.js';
import {$,$$,esc,openForm,field,option,confirmAction,toast} from './ui.js';

export class AmbienceUI {
  constructor(ctx){this.ctx=ctx;this.selectedId=null;}
  selected(){return this.ctx.state().ambiences.find(a=>a.id===this.selectedId)||this.ctx.state().ambiences[0];}
  render(root){
    this.root=root;const state=this.ctx.state(),preset=this.selected();if(preset)this.selectedId=preset.id;
    root.innerHTML=`<div class="library-heading"><div><div class="eyebrow">COMPONHA O SOM DO SEU UNIVERSO</div><h1>Ambientes <span class="count-badge">${state.ambiences.length}</span></h1><p>Loops, efeitos e pequenos acontecimentos. Tudo no seu ritmo.</p></div><button class="btn primary" id="newAmbience">${icon('plus')} Novo ambiente</button></div><div class="soundpad-layout"><aside class="playlist-sidebar"><span class="section-eyebrow">AMBIENTES SALVOS</span>${state.ambiences.map(a=>`<button class="playlist-nav ${a.id===preset?.id?'active':''}" data-ambience-select="${esc(a.id)}">${icon('rain')}<span>${esc(a.name)}</span><small>${a.layers.length}</small></button>`).join('')}<div class="library-info">${icon('info')}<p>O ambiente continua tocando ao navegar e durante o carregamento da próxima trilha.</p></div></aside><section class="soundpad-main">${preset?`<header class="soundpad-head"><div><span class="section-eyebrow">SEU SOUNDPAD</span><h2>${esc(preset.name)}</h2><p>${esc(preset.description||'Crie uma combinação de sons para esta atmosfera.')}</p></div><div class="heading-actions"><button class="icon-btn" id="editAmbience" title="Editar ambiente" aria-label="Editar ambiente">${icon('edit')}</button><button class="icon-btn" id="copyAmbience" title="Duplicar ambiente" aria-label="Duplicar ambiente">${icon('copy')}</button><button class="btn primary" id="playAmbience">${icon('play')} Ativar ambiente</button></div></header><div class="soundpad-status"><span class="status-dot"></span><span id="ambienceStatus">Pronto para tocar</span><small>Alterações salvas automaticamente</small></div><div class="section-heading"><h3>Camadas do ambiente</h3><button class="btn outline small" id="addAmbienceLayer">${icon('plus')} Adicionar camada</button></div><div class="sound-layer-grid">${preset.layers.map(l=>`<article class="sound-layer-card ${l.enabled===false?'disabled':''}"><header><span class="sound-layer-art">${icon(l.mode==='random'?'bolt':'rain')}</span><label class="sound-toggle"><input type="checkbox" data-amb-enabled="${esc(l.id)}" aria-label="Ativar ${esc(l.name)}" ${l.enabled!==false?'checked':''}><span></span></label><button class="icon-btn" data-edit-amb-layer="${esc(l.id)}" aria-label="Configurar ${esc(l.name)}">${icon('sliders')}</button></header><h3>${esc(l.name)}</h3><p>${esc(state.audioAssets.find(a=>a.id===l.assetId)?.name||'Arquivo ausente')}</p><div class="sound-layer-mode"><span>${l.mode==='random'?'OCASIONAL':'LOOP CONTÍNUO'}</span><small>${l.mode==='random'?`${l.minInterval}–${l.maxInterval}s`:'∞'}</small></div><div class="sound-layer-volume"><input type="range" data-amb-volume="${esc(l.id)}" min="0" max="100" value="${Math.round(l.volume*100)}" aria-label="Volume ${esc(l.name)}"><output data-amb-value="${esc(l.id)}">${Math.round(l.volume*100)}%</output></div></article>`).join('')||`<button class="sound-layer-empty" id="addFirstAmbLayer">${icon('plus')} Adicione chuva, vento, fogo ou outro arquivo.</button>`}</div><div class="section-heading"><h3>Disparos manuais</h3><button class="btn subtle small" id="addAmbiencePad">${icon('plus')} Adicionar efeito</button></div><div class="sound-pad-grid">${preset.pads.map(id=>state.audioAssets.find(a=>a.id===id)).filter(Boolean).map(a=>`<div class="sound-pad-wrap"><button class="sound-pad" data-amb-pad="${esc(a.id)}">${icon(/sino/i.test(a.name)?'bell':'bolt')}<strong>${esc(a.name)}</strong><small>TOCAR UMA VEZ</small></button><button class="pad-remove" data-remove-pad="${esc(a.id)}" aria-label="Retirar ${esc(a.name)} deste ambiente">×</button></div>`).join('')||'<p class="empty-small">Adicione botões para os efeitos que você usa com frequência.</p>'}</div><div class="soundpad-bottom"><button class="btn danger" id="stopAmbience">${icon('stop')} Encerrar ambiente com fade</button><p>As músicas e as camadas da cena continuam nos seus próprios canais.</p></div>`:`<div class="empty-state">${icon('rain')}<h3>Crie sua primeira atmosfera</h3><p>Adicione os áudios na biblioteca e combine suas camadas aqui.</p></div>`}</section></div>`;
    $('#newAmbience',root).onclick=()=>this.edit();$$('[data-ambience-select]',root).forEach(b=>b.onclick=()=>{this.selectedId=b.dataset.ambienceSelect;this.render(root);});
    if(!preset)return;
    $('#editAmbience',root).onclick=()=>this.edit(preset);$('#copyAmbience',root).onclick=()=>{const copy=clone(preset);copy.id=uid('ambience');copy.name+=' (cópia)';state.ambiences.push(copy);this.selectedId=copy.id;this.ctx.commit();};
    $('#playAmbience',root).onclick=async()=>{try{const bus=this.ctx.engine.ambiences;if(bus.active?.id===preset.id&&!bus.paused)bus.stop(preset.fadeOut??2);else await bus.apply(preset,{fade:preset.fadeIn??state.settings.crossfade});}catch(e){toast(e.message,true);}};
    $('#stopAmbience',root).onclick=()=>this.ctx.engine.ambiences.stop(preset.fadeOut??2);
    $('#addAmbienceLayer',root).onclick=()=>this.editLayer(preset);$('#addFirstAmbLayer',root)?.addEventListener('click',()=>this.editLayer(preset));
    $$('[data-edit-amb-layer]',root).forEach(b=>b.onclick=()=>this.editLayer(preset,preset.layers.find(l=>l.id===b.dataset.editAmbLayer)));
    $$('[data-amb-volume]',root).forEach(input=>input.oninput=()=>{const id=input.dataset.ambVolume,volume=Number(input.value)/100;preset.layers.find(l=>l.id===id).volume=volume;$(`[data-amb-value="${CSS.escape(id)}"]`,root).textContent=input.value+'%';if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.setVolume(id,volume);this.ctx.save();});
    $$('[data-amb-enabled]',root).forEach(input=>input.onchange=async()=>{const layer=preset.layers.find(l=>l.id===input.dataset.ambEnabled);layer.enabled=input.checked;input.closest('.sound-layer-card').classList.toggle('disabled',!input.checked);this.ctx.save();if(this.ctx.engine.ambiences.active?.id===preset.id)try{await this.ctx.engine.ambiences.toggleLayer(layer.id,input.checked);}catch(e){toast(e.message,true);}});
    $$('[data-amb-pad]',root).forEach(button=>button.onclick=()=>{this.ctx.engine.oneShot(state.audioAssets.find(a=>a.id===button.dataset.ambPad)).catch(e=>toast(e.message,true));button.classList.add('fired');setTimeout(()=>button.classList.remove('fired'),500);});
    $$('[data-remove-pad]',root).forEach(button=>button.onclick=()=>{preset.pads=preset.pads.filter(id=>id!==button.dataset.removePad);this.ctx.commit();});$('#addAmbiencePad',root).onclick=()=>this.addPad(preset);
    this.update();
  }
  update(){if(!this.root?.isConnected||!$('#ambienceStatus',this.root))return;const bus=this.ctx.engine.ambiences,preset=this.selected(),active=bus.active?.id===preset?.id;$('#ambienceStatus',this.root).textContent=active?(bus.paused?'Ambiente pausado':`Em execução · ${bus.tracks.size} loops · ${bus.jobs.size} efeitos ocasionais`):bus.active?`Tocando: ${bus.active.name}`:'Pronto para tocar';$('#playAmbience',this.root).innerHTML=icon(active&&!bus.paused?'stop':'play')+(active&&!bus.paused?' Encerrar ambiente':active?' Retomar ambiente':' Ativar ambiente');}
  edit(preset=null){openForm({title:preset?'Editar ambiente':'Novo ambiente',body:field('Nome','name',preset?.name||'','required maxlength="120" placeholder="Floresta à noite, taverna, laboratório…"')+field('Descrição','description',preset?.description||'','maxlength="350"')+'<div class="form-grid">'+field('Entrada do ambiente (s)','fadeIn',preset?.fadeIn??2,'type="number" min="0" max="30" step="0.1" required')+field('Saída do ambiente (s)','fadeOut',preset?.fadeOut??2,'type="number" min="0" max="30" step="0.1" required')+'</div>'+(preset?'<button type="button" class="btn danger full" id="deleteAmbience">Excluir ambiente salvo</button>':''),onReady:root=>$('#deleteAmbience',root)?.addEventListener('click',()=>confirmAction('Excluir ambiente?',`O preset “${preset.name}” será excluído. Os arquivos de áudio continuam na biblioteca.`,()=>{if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.stop(0);this.ctx.state().ambiences=this.ctx.state().ambiences.filter(a=>a.id!==preset.id);this.selectedId=null;this.ctx.commit();})),onSubmit:form=>{const name=String(form.get('name')).trim();if(!name)throw new Error('Informe um nome.');const values={name,description:String(form.get('description')).trim(),fadeIn:Number(form.get('fadeIn')),fadeOut:Number(form.get('fadeOut'))};if(preset)Object.assign(preset,values);else{const p={id:uid('ambience'),...values,layers:[],pads:[]};this.ctx.state().ambiences.push(p);this.selectedId=p.id;}this.ctx.commit();}});}
  editLayer(preset,layer=null){const assets=this.ctx.state().audioAssets.filter(a=>a.provider!=='youtube');if(!assets.length){toast('Envie um arquivo de áudio pela biblioteca.',true);return;}
    openForm({title:layer?'Editar camada do ambiente':'Nova camada de ambiente',body:field('Nome da camada','name',layer?.name||'','required maxlength="100" placeholder="Chuva no telhado…"')+'<label class="field"><span>Arquivo da biblioteca</span><select name="assetId">'+assets.map(a=>option(a.id,a.name,a.id===layer?.assetId)).join('')+'</select></label><div class="form-grid"><label class="field"><span>Comportamento</span><select name="mode" id="ambientMode">'+[['loop','Loop contínuo'],['random','Efeito ocasional']].map(([v,l])=>option(v,l,v===(layer?.mode||'loop'))).join('')+'</select></label>'+field('Volume (%)','volume',Math.round((layer?.volume??.5)*100),'type="number" min="0" max="100" required')+'</div><div class="form-grid" id="randomIntervals">'+field('Intervalo mínimo (s)','minInterval',layer?.minInterval??15,'type="number" min="0.1" max="3600" step="0.1" required')+field('Intervalo máximo (s)','maxInterval',layer?.maxInterval??45,'type="number" min="0.1" max="3600" step="0.1" required')+'</div><p class="form-hint">No modo ocasional, o próximo intervalo é sorteado depois que o efeito termina. Isso evita repetições mecânicas e sobreposição do mesmo som.</p>'+(layer?'<button type="button" class="btn danger full" id="deleteAmbLayer">Remover camada do ambiente</button>':''),onReady:root=>{const update=()=>{$('#randomIntervals',root).hidden=$('#ambientMode',root).value!=='random';$$('input',$('#randomIntervals',root)).forEach(i=>i.disabled=$('#randomIntervals',root).hidden);};$('#ambientMode',root).onchange=update;update();$('#deleteAmbLayer',root)?.addEventListener('click',()=>{preset.layers=preset.layers.filter(l=>l!==layer);$('#appDialog').close();this.ctx.commit();if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.apply(preset,{fade:.5}).catch(e=>toast(e.message,true));});},onSubmit:form=>{const name=String(form.get('name')).trim(),mode=form.get('mode'),min=Number(form.get('minInterval')),max=Number(form.get('maxInterval'));if(!name)throw new Error('Informe um nome.');if(mode==='random'&&max<min)throw new Error('O intervalo máximo deve ser maior ou igual ao mínimo.');const value={id:layer?.id||uid('amb-layer'),name,assetId:form.get('assetId'),mode,volume:Number(form.get('volume'))/100,enabled:layer?.enabled!==false,...(mode==='random'?{minInterval:min,maxInterval:max}:{})};if(layer)Object.assign(layer,value);else preset.layers.push(value);this.ctx.commit();if(this.ctx.engine.ambiences.active?.id===preset.id)this.ctx.engine.ambiences.apply(preset,{fade:.5}).catch(e=>toast(e.message,true));}});
  }
  addPad(preset){const assets=this.ctx.state().audioAssets.filter(a=>a.provider!=='youtube'&&!preset.pads.includes(a.id));if(!assets.length){toast('Todos os arquivos disponíveis já estão neste painel. Envie mais áudios na biblioteca.');return;}openForm({title:'Adicionar disparo manual',body:'<label class="field"><span>Efeito da biblioteca</span><select name="assetId">'+assets.map(a=>option(a.id,a.name)).join('')+'</select></label>',submit:'Adicionar efeito',onSubmit:form=>{preset.pads.push(form.get('assetId'));this.ctx.commit();}});}
}
